import{A as e,E as t,d as n,l as r,p as i,s as a}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as o}from"./app-fnFKaiE5.js";var s=JSON.parse(`{"path":"/Linux/07_Nginx/07_%E7%BC%93%E5%AD%98%E4%B8%8E%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96/02_%E6%B5%8F%E8%A7%88%E5%99%A8%E7%BC%93%E5%AD%98%E7%AD%96%E7%95%A5.html","title":"浏览器缓存策略","lang":"zh-CN","frontmatter":{"title":"浏览器缓存策略","icon":"fa6-solid:clock-rotate-left","order":2,"category":["Linux","Nginx"],"tag":["Nginx","缓存","Cache-Control","ETag","Last-Modified","浏览器缓存","Service Worker"]},"git":{"createdTime":1780631738000,"updatedTime":1780712648000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":18.67,"words":5601},"filePathRelative":"Linux/07_Nginx/07_缓存与性能优化/02_浏览器缓存策略.md"}`),c={name:`02_浏览器缓存策略.md`};function l(o,s,c,l,u,d){let f=e(`Mermaid`);return t(),r(`div`,null,[s[0]||=n(`<h1 id="浏览器缓存策略" tabindex="-1"><a class="header-anchor" href="#浏览器缓存策略"><span>浏览器缓存策略</span></a></h1><p>浏览器缓存是 Web 性能优化中投入产出比最高的手段之一——一次正确的缓存配置，可以让后续访问零网络开销。但缓存策略远不止设置 <code>Cache-Control: max-age</code> 那么简单，它涉及强缓存与协商缓存的决策、不同资源类型的差异策略、缓存失效与更新的协同，以及与 CDN/Service Worker 的配合。本文将系统讲解 Nginx 侧的浏览器缓存配置。</p><h2 id="_1-http-缓存机制概述" tabindex="-1"><a class="header-anchor" href="#_1-http-缓存机制概述"><span>1. HTTP 缓存机制概述</span></a></h2><h3 id="_1-1-强缓存-vs-协商缓存" tabindex="-1"><a class="header-anchor" href="#_1-1-强缓存-vs-协商缓存"><span>1.1 强缓存 vs 协商缓存</span></a></h3><p>HTTP 缓存分为两大类，核心区别在于 <strong>是否需要向服务器发请求</strong>：</p><table><thead><tr><th>类型</th><th>机制</th><th>是否发请求</th><th>响应</th><th>适用场景</th></tr></thead><tbody><tr><td>强缓存</td><td>Cache-Control / Expires</td><td>否（未过期时）</td><td>直接使用本地缓存</td><td>不常变化的资源</td></tr><tr><td>协商缓存</td><td>ETag / Last-Modified</td><td>是（条件请求）</td><td>304 Not Modified 或 200</td><td>可能变化的资源</td></tr></tbody></table>`,6),i(f,{code:``}),s[1]||=a(`h3`,{id:`_1-2-缓存决策流程`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#_1-2-缓存决策流程`},[a(`span`,null,`1.2 缓存决策流程`)])],-1),i(f,{code:``}),s[2]||=n(`<div class="hint-container important"><p class="hint-container-title">缓存策略的黄金法则</p><ul><li><strong>内容不变</strong>的资源（带哈希文件名）：<code>Cache-Control: public, max-age=31536000, immutable</code></li><li><strong>内容可能变</strong>的资源（HTML 入口）：<code>Cache-Control: no-cache</code>（每次验证）或短 <code>max-age</code></li><li><strong>敏感数据</strong>（用户私有 API）：<code>Cache-Control: no-store</code></li><li><strong>公共资源</strong>（CDN 缓存）：<code>Cache-Control: public</code></li></ul></div><h2 id="_2-cache-control-指令详解" tabindex="-1"><a class="header-anchor" href="#_2-cache-control-指令详解"><span>2. Cache-Control 指令详解</span></a></h2><p><code>Cache-Control</code> 是 HTTP/1.1 引入的缓存控制头，取代了 HTTP/1.0 的 <code>Expires</code>，提供了更精细的控制。</p><h3 id="_2-1-max-age" tabindex="-1"><a class="header-anchor" href="#_2-1-max-age"><span>2.1 max-age</span></a></h3><p><code>max-age</code> 指定资源在缓存中的最大存活时间（秒），从响应被生成时开始计算：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 1年缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=31536000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 10分钟缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.html$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=600&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 立即过期</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-2-no-cache" tabindex="-1"><a class="header-anchor" href="#_2-2-no-cache"><span>2.2 no-cache</span></a></h3><p><code>no-cache</code> 的名字容易误导——它 <strong>不是&quot;不缓存&quot;</strong>，而是&quot;缓存前必须验证&quot;：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># no-cache：浏览器可以缓存，但每次使用前必须发条件请求验证</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /html/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 实际效果类似 max-age=0, must-revalidate</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 注意：严格来说并不等效。no-cache 强制使用前必须验证；</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # max-age=0 使响应立即过期 + must-revalidate 禁止使用过期缓存。</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 实际行为相似，但语义不完全一致（参见 RFC 7234）</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 实际效果：浏览器缓存资源，但每次访问都发请求验证</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果服务器返回 304，浏览器使用缓存</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 如果服务器返回 200，浏览器替换缓存</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">no-cache ≠ no-store</p><p>这是最常见的缓存概念混淆：</p><ul><li><code>no-cache</code>：<strong>可以缓存</strong>，但使用前必须验证</li><li><code>no-store</code>：<strong>绝对不缓存</strong>，任何情况下都不存储响应</li></ul><p>使用场景：</p><ul><li><code>no-cache</code>：HTML 页面、可能更新的 API 响应</li><li><code>no-store</code>：银行页面、登录响应、敏感个人信息</li></ul></div><h3 id="_2-3-no-store" tabindex="-1"><a class="header-anchor" href="#_2-3-no-store"><span>2.3 no-store</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># no-store：完全禁止任何形式的缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/user/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-store, no-cache, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Pragma </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># HTTP/1.0 兼容</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Expires </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;">;        </span><span style="color:#7F848E;font-style:italic;"># HTTP/1.0 兼容</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-4-public-private" tabindex="-1"><a class="header-anchor" href="#_2-4-public-private"><span>2.4 public / private</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># public：任何缓存（浏览器、CDN、代理）都可以缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /static/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=86400&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># private：只有浏览器可以缓存，中间代理/CDN不得缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/profile/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;private, max-age=300&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 用户个人数据，CDN缓存会导致数据泄露</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>指令</th><th>浏览器缓存</th><th>CDN/代理缓存</th><th>典型场景</th></tr></thead><tbody><tr><td>public</td><td>允许</td><td>允许</td><td>静态资源、公共API</td></tr><tr><td>private</td><td>允许</td><td>禁止</td><td>用户私有数据</td></tr><tr><td>（无指令）</td><td>允许</td><td>视情况而定</td><td>默认行为</td></tr></tbody></table><h3 id="_2-5-must-revalidate-proxy-revalidate" tabindex="-1"><a class="header-anchor" href="#_2-5-must-revalidate-proxy-revalidate"><span>2.5 must-revalidate / proxy-revalidate</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># must-revalidate：缓存过期后必须验证，不能使用过期缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/data/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=300, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 缓存5分钟，过期后必须向服务器验证</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 不能在验证前使用过期缓存（即使看起来仍然有效）</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># proxy-revalidate：仅对共享缓存（CDN/代理）要求重新验证</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /shared/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=300, proxy-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 浏览器可以自由使用过期缓存</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 但代理/CDN必须验证</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-6-immutable" tabindex="-1"><a class="header-anchor" href="#_2-6-immutable"><span>2.6 immutable</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># immutable：告诉浏览器，即使刷新页面也不发验证请求</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=31536000, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 适用条件：文件名包含内容哈希，如 app.3a4b5c6d.js</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Chrome 刷新时通常会对 max-age 资源发条件请求</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # immutable 明确告诉浏览器：不需要验证</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">immutable 的价值</p><p>根据 HTTP Archive 统计，页面刷新时约 40% 的请求是条件验证请求（304 响应），其中大部分是带哈希的静态资源。<code>immutable</code> 可以消除这些无意义的验证请求，在刷新场景下节省约 20% 的网络请求。</p></div><h3 id="_2-7-stale-while-revalidate-stale-if-error" tabindex="-1"><a class="header-anchor" href="#_2-7-stale-while-revalidate-stale-if-error"><span>2.7 stale-while-revalidate / stale-if-error</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># stale-while-revalidate：允许在后台刷新缓存的同时返回过期缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/articles/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=300, stale-while-revalidate=60&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 缓存5分钟有效</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 过期后的60秒内，可以返回过期缓存，同时后台异步刷新</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 用户始终得到快速响应，数据最多延迟60秒</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># stale-if-error：服务器错误时允许使用过期缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/config/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=300, stale-if-error=3600&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 服务器返回5xx错误时，可以在1小时内返回过期缓存</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 提升容错能力</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-8-nginx-中-cache-control-的完整配置" tabindex="-1"><a class="header-anchor" href="#_2-8-nginx-中-cache-control-的完整配置"><span>2.8 Nginx 中 Cache-Control 的完整配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    root </span><span style="color:#ABB2BF;">/var/www;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ========== 强缓存：带哈希的静态资源 ==========</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # Nginx expires 指令会自动添加 Cache-Control: max-age</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # add_header 会追加，不会覆盖 expires 生成的头</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ========== 协商缓存：HTML 入口 ==========</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.html$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">-1;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # ETag 由 Nginx 自动生成</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ========== 短缓存：图片资源 ==========</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(jpg|jpeg|png|gif|webp|svg|ico)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ========== 短缓存 + 后台刷新：API ==========</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /api/articles/ {</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=300, stale-while-revalidate=60&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_pass </span><span style="color:#ABB2BF;">http://backend;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ========== 不缓存：用户私有 API ==========</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /api/user/ {</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;private, no-cache, no-store, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Pragma </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Expires </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_pass </span><span style="color:#ABB2BF;">http://backend;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-expires-指令与过期时间计算" tabindex="-1"><a class="header-anchor" href="#_3-expires-指令与过期时间计算"><span>3. expires 指令与过期时间计算</span></a></h2><p><code>expires</code> 是 Nginx 内置指令，它会同时设置 <code>Expires</code> 和 <code>Cache-Control: max-age</code> 两个响应头。</p><h3 id="_3-1-expires-语法" tabindex="-1"><a class="header-anchor" href="#_3-1-expires-语法"><span>3.1 expires 语法</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 绝对时间偏移</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#D19A66;">1h</span><span style="color:#ABB2BF;">;       </span><span style="color:#7F848E;font-style:italic;"># 1小时后过期</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;      </span><span style="color:#7F848E;font-style:italic;"># 30天后过期</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#D19A66;">365d</span><span style="color:#ABB2BF;">;     </span><span style="color:#7F848E;font-style:italic;"># 365天后过期</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#ABB2BF;">1y;       </span><span style="color:#7F848E;font-style:italic;"># 1年后过期（≈365天）</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 相对于 Last-Modified 的时间偏移</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#ABB2BF;">modified +1h;  </span><span style="color:#7F848E;font-style:italic;"># 修改时间 + 1小时</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 特定时间点</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#ABB2BF;">@15h30m;  </span><span style="color:#7F848E;font-style:italic;"># 今天15:30过期</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#ABB2BF;">@0h;      </span><span style="color:#7F848E;font-style:italic;"># 今天午夜过期</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 特殊值</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#ABB2BF;">epoch;    </span><span style="color:#7F848E;font-style:italic;"># Expires: Thu, 01 Jan 1970 00:00:01 GMT</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">                 # Cache-Control: no-cache</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#D19A66;">max</span><span style="color:#ABB2BF;">;      </span><span style="color:#7F848E;font-style:italic;"># Expires: Thu, 31 Dec 2037 23:55:55 GMT</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">                 # Cache-Control: max-age=315360000 (10年)</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#ABB2BF;">-1;       </span><span style="color:#7F848E;font-style:italic;"># 过去的时间，浏览器立即认为过期</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">                 # Cache-Control: no-cache</span></span>
<span class="line"><span style="color:#C678DD;">expires </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;      </span><span style="color:#7F848E;font-style:italic;"># 不修改 Expires 和 Cache-Control</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-expires-的工作原理" tabindex="-1"><a class="header-anchor" href="#_3-2-expires-的工作原理"><span>3.2 expires 的工作原理</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># expires 30d 会生成两个头：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Expires: &lt;当前时间 + 30天&gt;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Cache-Control: max-age=2592000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 注意：如果同时使用了 add_header Cache-Control</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># expires 生成的 max-age 和 add_header 的值会同时存在</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 这可能导致冲突</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 推荐方式1：只用 expires</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /images/ {</span></span>
<span class="line"><span style="color:#C678DD;">    expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># 自动设置 Expires 和 Cache-Control: max-age=2592000</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 推荐方式2：只用 add_header（更灵活）</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /images/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=2592000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 不使用 expires，手动控制 Cache-Control</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">expires 与 add_header 的冲突</p><p><code>expires</code> 指令会自动生成 <code>Cache-Control: max-age=xxx</code>，而 <code>add_header Cache-Control</code> 会追加另一个 <code>Cache-Control</code> 头。如果两者同时使用，响应中会出现两个 <code>Cache-Control</code> 头，浏览器行为不可预测。</p><p>解决方案：</p><ol><li>只用 <code>expires</code>（简单场景）</li><li>只用 <code>add_header Cache-Control</code>（需要精细控制时）</li><li>用 <code>expires off</code> 禁用 expires，再用 <code>add_header</code></li></ol></div><h3 id="_3-3-条件化-expires" tabindex="-1"><a class="header-anchor" href="#_3-3-条件化-expires"><span>3.3 条件化 expires</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 根据 $sent_http_content_type 动态设置缓存时间</span></span>
<span class="line"><span style="color:#C678DD;">map</span><span style="color:#ABB2BF;"> $</span><span style="color:#E06C75;font-style:italic;">sent_http_content_type</span><span style="color:#ABB2BF;"> $</span><span style="color:#E06C75;">cache_control</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#ABB2BF;">    text/html                    </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    text/css                     </span><span style="color:#98C379;">&quot;public, max-age=31536000, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    application/javascript       </span><span style="color:#98C379;">&quot;public, max-age=31536000, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    image/jpeg                   </span><span style="color:#98C379;">&quot;public, max-age=2592000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    image/png                    </span><span style="color:#98C379;">&quot;public, max-age=2592000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    image/webp                   </span><span style="color:#98C379;">&quot;public, max-age=2592000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    image/svg+xml                </span><span style="color:#98C379;">&quot;public, max-age=2592000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    application/json             </span><span style="color:#98C379;">&quot;private, no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#D19A66;">    default</span><span style="color:#98C379;">                      &quot;public, max-age=3600&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    expires </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control $</span><span style="color:#E06C75;">cache_control</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-etag-last-modified-响应头与验证请求" tabindex="-1"><a class="header-anchor" href="#_4-etag-last-modified-响应头与验证请求"><span>4. ETag / Last-Modified 响应头与验证请求</span></a></h2><h3 id="_4-1-etag-机制" tabindex="-1"><a class="header-anchor" href="#_4-1-etag-机制"><span>4.1 ETag 机制</span></a></h3><p>ETag（Entity Tag）是资源的唯一标识符，Nginx 默认基于文件的最后修改时间和大小生成：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">http</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    etag </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># 默认开启</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ETag 格式：&quot;&lt;mtime_hex&gt;-&lt;size_hex&gt;&quot;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 例如：ETag: &quot;65a1b2c0-1f4a&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ETag 验证流程：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 首次请求：</span></span>
<span class="line"><span>   GET /style.css</span></span>
<span class="line"><span>   → 200 OK</span></span>
<span class="line"><span>   ETag: &quot;65a1b2c0-1f4a&quot;</span></span>
<span class="line"><span>   Cache-Control: max-age=3600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 缓存过期后，浏览器发送条件请求：</span></span>
<span class="line"><span>   GET /style.css</span></span>
<span class="line"><span>   If-None-Match: &quot;65a1b2c0-1f4a&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3a. 文件未修改：</span></span>
<span class="line"><span>   → 304 Not Modified</span></span>
<span class="line"><span>   ETag: &quot;65a1b2c0-1f4a&quot;</span></span>
<span class="line"><span>   （不传输响应体，节省带宽）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3b. 文件已修改：</span></span>
<span class="line"><span>   → 200 OK</span></span>
<span class="line"><span>   ETag: &quot;65b3d4e0-2a8f&quot;</span></span>
<span class="line"><span>   （传输新内容）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-last-modified-机制" tabindex="-1"><a class="header-anchor" href="#_4-2-last-modified-机制"><span>4.2 Last-Modified 机制</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">http</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Last-Modified 默认开启</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 值为文件的最后修改时间</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 例如：Last-Modified: Wed, 03 Jan 2024 10:30:00 GMT</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Last-Modified 验证流程：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 首次请求：</span></span>
<span class="line"><span>   GET /page.html</span></span>
<span class="line"><span>   → 200 OK</span></span>
<span class="line"><span>   Last-Modified: Wed, 03 Jan 2024 10:30:00 GMT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. 缓存过期后，浏览器发送条件请求：</span></span>
<span class="line"><span>   GET /page.html</span></span>
<span class="line"><span>   If-Modified-Since: Wed, 03 Jan 2024 10:30:00 GMT</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3a. 文件未修改：</span></span>
<span class="line"><span>   → 304 Not Modified</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3b. 文件已修改：</span></span>
<span class="line"><span>   → 200 OK</span></span>
<span class="line"><span>   Last-Modified: Thu, 04 Jan 2024 15:20:00 GMT</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-etag-vs-last-modified" tabindex="-1"><a class="header-anchor" href="#_4-3-etag-vs-last-modified"><span>4.3 ETag vs Last-Modified</span></a></h3><table><thead><tr><th>特性</th><th>ETag</th><th>Last-Modified</th></tr></thead><tbody><tr><td>精度</td><td>精确（字节级）</td><td>秒级（1秒内多次修改无法区分）</td></tr><tr><td>可靠性</td><td>高</td><td>中（修改时间变了但内容可能没变）</td></tr><tr><td>请求头</td><td>If-None-Match</td><td>If-Modified-Since</td></tr><tr><td>响应头</td><td>ETag</td><td>Last-Modified</td></tr><tr><td>计算成本</td><td>需要计算标识</td><td>直接读取文件元数据</td></tr><tr><td>分布式一致性</td><td>依赖生成算法</td><td>基于时间，跨服务器可能不同</td></tr></tbody></table><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 当两者同时存在时，浏览器会同时发送：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If-None-Match: &quot;65a1b2c0-1f4a&quot;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># If-Modified-Since: Wed, 03 Jan 2024 10:30:00 GMT</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Nginx 只验证 If-None-Match，完全忽略 If-Modified-Since</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 只有当请求不包含 If-None-Match 时，才会检查 If-Modified-Since</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 这是 RFC 7232 的规定：ETag 验证器优先级高于 Last-Modified</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">ETag 优先级更高</p><p>当请求同时包含 <code>If-None-Match</code> 和 <code>If-Modified-Since</code> 时，Nginx <strong>只检查</strong> <code>If-None-Match</code>，<code>If-Modified-Since</code> 被完全忽略——不会作为后备验证手段。只有 <code>If-None-Match</code> 不存在时，才会检查 <code>If-Modified-Since</code>。这是 RFC 7232 的规定，强验证器（ETag）优先于弱验证器（Last-Modified）。</p></div><h3 id="_4-4-关闭-etag-的场景" tabindex="-1"><a class="header-anchor" href="#_4-4-关闭-etag-的场景"><span>4.4 关闭 ETag 的场景</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 某些场景需要关闭 ETag</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 1. 多服务器部署且 ETag 不一致</span></span>
<span class="line"><span style="color:#C678DD;">    etag </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 2. 使用 CDN 且 CDN 有自己的缓存验证机制</span></span>
<span class="line"><span style="color:#C678DD;">    etag </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 3. 动态内容（每次生成的 ETag 不同，无意义）</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /api/ {</span></span>
<span class="line"><span style="color:#C678DD;">        etag </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-nginx-条件请求处理-if-modified-since" tabindex="-1"><a class="header-anchor" href="#_5-nginx-条件请求处理-if-modified-since"><span>5. nginx 条件请求处理：if_modified_since</span></a></h2><p><code>if_modified_since</code> 指令控制 Nginx 如何处理 <code>If-Modified-Since</code> 请求头：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">http</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # off：忽略 If-Modified-Since，总是返回完整内容</span></span>
<span class="line"><span style="color:#C678DD;">    if_modified_since </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # exact：精确匹配（默认），修改时间完全一致才返回 304</span></span>
<span class="line"><span style="color:#C678DD;">    if_modified_since </span><span style="color:#ABB2BF;">exact;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # before：修改时间早于或等于 If-Modified-Since 才返回 304</span></span>
<span class="line"><span style="color:#C678DD;">    if_modified_since </span><span style="color:#ABB2BF;">before;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 实际场景</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 静态文件：使用精确匹配（默认）</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /static/ {</span></span>
<span class="line"><span style="color:#C678DD;">        if_modified_since </span><span style="color:#ABB2BF;">exact;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 动态内容：关闭 Last-Modified 验证</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /api/ {</span></span>
<span class="line"><span style="color:#C678DD;">        if_modified_since </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        etag </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 定期更新的文件：使用 before，容忍微小时间差</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /feeds/ {</span></span>
<span class="line"><span style="color:#C678DD;">        if_modified_since </span><span style="color:#ABB2BF;">before;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_6-不同资源类型缓存策略" tabindex="-1"><a class="header-anchor" href="#_6-不同资源类型缓存策略"><span>6. 不同资源类型缓存策略</span></a></h2><h3 id="_6-1-资源缓存矩阵" tabindex="-1"><a class="header-anchor" href="#_6-1-资源缓存矩阵"><span>6.1 资源缓存矩阵</span></a></h3>`,55),i(f,{code:``}),s[3]||=n(`<h3 id="_6-2-完整的按类型缓存配置" tabindex="-1"><a class="header-anchor" href="#_6-2-完整的按类型缓存配置"><span>6.2 完整的按类型缓存配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    root </span><span style="color:#ABB2BF;">/var/www;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 1. 带 Hash 的静态资源</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 文件名如: app.3a4b5c6d.js, chunk.1e2f3g4h.css</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 内容变化 → 哈希变化 → URL变化 → 旧缓存自然失效</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # immutable: 即使刷新也不验证，性能最优</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 2. HTML 入口文件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 必须每次验证，因为引用的 CSS/JS 哈希可能变了</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.html$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 使用协商缓存（ETag/Last-Modified）</span></span>
<span class="line"><span style="color:#C678DD;">        etag </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 3. 图片资源</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(jpg|jpeg|png|gif|webp|avif|svg|ico)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        etag </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 4. 字体文件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(woff|woff2|ttf|otf|eot)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Access-Control-Allow-Origin </span><span style="color:#98C379;">&quot;*&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 5. 视频/音频</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(mp4|webm|ogg|mp3|wav)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        aio </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        directio </span><span style="color:#D19A66;">5m</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 6. JSON/XML 数据</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(json|xml)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=300&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 5分钟缓存，适合不频繁变化的API数据</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 7. Service Worker</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/sw.js </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # SW 必须每次验证更新</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 8. Favicon</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/favicon.ico </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#D19A66;">7d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        access_log </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        log_not_found </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 9. robots.txt / sitemap.xml</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ============================</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/robots.txt </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#D19A66;">1d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        access_log </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        log_not_found </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-前后端协同的缓存策略" tabindex="-1"><a class="header-anchor" href="#_6-3-前后端协同的缓存策略"><span>6.3 前后端协同的缓存策略</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 前端构建产物目录结构</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># /var/www/app/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ├── index.html           ← no-cache</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ├── assets/</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># │   ├── app.3a4b5c.js   ← immutable, 1y</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># │   ├── app.1e2f3g.css  ← immutable, 1y</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># │   └── logo.5h6i7j.png ← immutable, 1y</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ├── sw.js                ← no-cache</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># └── favicon.ico          ← 7d</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">app.example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    root </span><span style="color:#ABB2BF;">/var/www/app;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # HTML：no-cache + ETag</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/index.html </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        etag </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 带 Hash 的资源：最长缓存</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 其他 HTML 路由回退（SPA）</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        try_files </span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">uri</span><span style="color:#ABB2BF;"> /index.html;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_7-缓存清除与版本化-url" tabindex="-1"><a class="header-anchor" href="#_7-缓存清除与版本化-url"><span>7. 缓存清除与版本化 URL</span></a></h2><h3 id="_7-1-缓存更新的困境" tabindex="-1"><a class="header-anchor" href="#_7-1-缓存更新的困境"><span>7.1 缓存更新的困境</span></a></h3><p>缓存的核心矛盾是：<strong>缓存时间越长，性能越好；但更新越困难</strong>。解决方案是版本化 URL：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># 方案1：查询参数版本号（不推荐）</span></span>
<span class="line"><span>/style.css?v=1.2.3</span></span>
<span class="line"><span># 问题：某些 CDN/代理会忽略查询参数，返回旧版本</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 方案2：文件名哈希（推荐）</span></span>
<span class="line"><span>/app.3a4b5c6d.js</span></span>
<span class="line"><span># 内容变化 → 哈希变化 → URL变化 → 全新资源，无缓存冲突</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-nginx-配置版本化策略" tabindex="-1"><a class="header-anchor" href="#_7-2-nginx-配置版本化策略"><span>7.2 Nginx 配置版本化策略</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 方案1：构建工具生成哈希文件名（最佳实践）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Vite/Webpack 自动输出: dist/assets/app.3a4b5c6d.js</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 方案2：目录版本化</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # /v1.2.3/css/style.css → /var/www/releases/v1.2.3/css/style.css</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~ </span><span style="color:#E06C75;">^/v([\\d.]+)/(.*)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        root </span><span style="color:#ABB2BF;">/var/www/releases;</span></span>
<span class="line"><span style="color:#C678DD;">        try_files </span><span style="color:#ABB2BF;">/v$</span><span style="color:#E06C75;">1</span><span style="color:#ABB2BF;">/$</span><span style="color:#E06C75;">2</span><span style="color:#D19A66;"> =404</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 方案3：服务端主动清除缓存（配合 proxy_cache_purge）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 见后续代理缓存章节</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-缓存清除技巧" tabindex="-1"><a class="header-anchor" href="#_7-3-缓存清除技巧"><span>7.3 缓存清除技巧</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 方法1：修改文件名（最可靠）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 旧: /assets/app.js → 新: /assets/app.abc123.js</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法2：使用 sitemap 通知搜索引擎</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/sitemap.xml </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=86400&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法3：通过 URL 参数强制刷新（调试用）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 Nginx 中不做特殊处理，只是绕过浏览器缓存</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># curl -H &quot;Cache-Control: no-cache&quot; https://example.com/style.css</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 方法4：对特定路径禁用缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /preview/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-store, no-cache, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Pragma </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Expires </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_8-service-worker-与-nginx-配合" tabindex="-1"><a class="header-anchor" href="#_8-service-worker-与-nginx-配合"><span>8. Service Worker 与 Nginx 配合</span></a></h2><h3 id="_8-1-service-worker-缓存层级" tabindex="-1"><a class="header-anchor" href="#_8-1-service-worker-缓存层级"><span>8.1 Service Worker 缓存层级</span></a></h3><p>Service Worker 在浏览器和网络之间增加了一个可编程的缓存层：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>请求 → Service Worker 缓存 → HTTP 缓存 → 网络请求 → 服务器</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_8-2-service-worker-文件的缓存配置" tabindex="-1"><a class="header-anchor" href="#_8-2-service-worker-文件的缓存配置"><span>8.2 Service Worker 文件的缓存配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Service Worker 文件必须每次验证</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/sw.js </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache, no-store, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Service-Worker-Allowed </span><span style="color:#98C379;">&quot;/&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 确保浏览器总是获取最新的 SW</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Precache Manifest（构建工具生成）</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/precache-manifest.js </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Workbox 运行时</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /workbox/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">Service Worker 缓存与 HTTP 缓存的交互</p><p>Service Worker 的 <code>fetch</code> 事件在 HTTP 缓存之前触发。当 SW 使用 <code>cache.match()</code> 时，它可能命中 SW Cache；当 SW 使用 <code>fetch()</code> 发起网络请求时，该请求仍会经过 HTTP 缓存。如果 HTTP 缓存返回 304，SW 收到的是缓存的 Response 对象。</p><p>关键规则：</p><ol><li>SW 文件本身必须 <code>Cache-Control: no-cache</code>，确保浏览器每次都获取最新版本</li><li>SW 的 <code>install</code> 事件中预缓存的资源应该有长 <code>max-age</code>，因为 SW 会管理其更新</li><li>SW 的 <code>fetch</code> 策略应与 HTTP 缓存策略协调，避免双重缓存导致数据不一致</li></ol></div><h3 id="_8-3-sw-与-http-缓存的协调配置" tabindex="-1"><a class="header-anchor" href="#_8-3-sw-与-http-缓存的协调配置"><span>8.3 SW 与 HTTP 缓存的协调配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    root </span><span style="color:#ABB2BF;">/var/www/pwa;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # SW 文件：不缓存</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/sw.js </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-store&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # App Shell（HTML）：短缓存，SW 会优先处理</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/index.html </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 静态资源：长缓存 + immutable</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # SW 的 CacheFirst 策略会直接使用 SW Cache</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # HTTP 缓存作为 fallback</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # API：SW 可以使用 NetworkFirst 策略</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /api/ {</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_pass </span><span style="color:#ABB2BF;">http://backend;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_8-4-pwa-完整配置示例" tabindex="-1"><a class="header-anchor" href="#_8-4-pwa-完整配置示例"><span>8.4 PWA 完整配置示例</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl http2;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">pwa.example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    root </span><span style="color:#ABB2BF;">/var/www/pwa;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # SSL 配置</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">/etc/ssl/certs/pwa.crt;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/ssl/private/pwa.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # PWA 必须使用 HTTPS</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Service Worker 只能在 HTTPS 或 localhost 下注册</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 安全头</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Frame-Options </span><span style="color:#98C379;">&quot;SAMEORIGIN&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Strict-Transport-Security </span><span style="color:#98C379;">&quot;max-age=31536000; includeSubDomains&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Manifest 文件</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/manifest.json </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=86400&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Access-Control-Allow-Origin </span><span style="color:#98C379;">&quot;*&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # Service Worker</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/sw.js </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-store, no-cache, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Service-Worker-Allowed </span><span style="color:#98C379;">&quot;/&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # HTML 入口</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        try_files </span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">uri</span><span style="color:#ABB2BF;"> /index.html;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 静态资源</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_9-缓存性能分析与监控" tabindex="-1"><a class="header-anchor" href="#_9-缓存性能分析与监控"><span>9. 缓存性能分析与监控</span></a></h2><h3 id="_9-1-缓存命中率分析" tabindex="-1"><a class="header-anchor" href="#_9-1-缓存命中率分析"><span>9.1 缓存命中率分析</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 通过自定义日志格式分析缓存命中情况</span></span>
<span class="line"><span style="color:#C678DD;">log_format </span><span style="color:#ABB2BF;">cache_analysis </span><span style="color:#98C379;">&#39;$</span><span style="color:#E06C75;">remote_addr</span><span style="color:#98C379;"> - $</span><span style="color:#E06C75;">remote_user</span><span style="color:#98C379;"> [$</span><span style="color:#E06C75;">time_local</span><span style="color:#98C379;">] &#39;</span></span>
<span class="line"><span style="color:#98C379;">                          &#39;&quot;$</span><span style="color:#E06C75;">request</span><span style="color:#98C379;">&quot; $</span><span style="color:#E06C75;">status</span><span style="color:#98C379;"> $</span><span style="color:#E06C75;">body_bytes_sent</span><span style="color:#98C379;"> &#39;</span></span>
<span class="line"><span style="color:#98C379;">                          &#39;&quot;$</span><span style="color:#E06C75;">http_referer</span><span style="color:#98C379;">&quot; &quot;$</span><span style="color:#E06C75;">http_user_agent</span><span style="color:#98C379;">&quot; &#39;</span></span>
<span class="line"><span style="color:#98C379;">                          &#39;cache_status=&quot;$</span><span style="color:#E06C75;">upstream_cache_status</span><span style="color:#98C379;">&quot; &#39;</span></span>
<span class="line"><span style="color:#98C379;">                          &#39;etag=&quot;$</span><span style="color:#E06C75;">sent_http_etag</span><span style="color:#98C379;">&quot; &#39;</span></span>
<span class="line"><span style="color:#98C379;">                          &#39;cache_control=&quot;$</span><span style="color:#E06C75;">sent_http_cache_control</span><span style="color:#98C379;">&quot;&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    access_log </span><span style="color:#ABB2BF;">/var/log/nginx/cache_analysis.log cache_analysis;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-2-缓存状态统计脚本" tabindex="-1"><a class="header-anchor" href="#_9-2-缓存状态统计脚本"><span>9.2 缓存状态统计脚本</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;">#!/bin/bash</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># cache_stats.sh - 分析 Nginx 缓存命中率</span></span>
<span class="line"><span style="color:#E06C75;">LOG_FILE</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;/var/log/nginx/cache_analysis.log&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;=== Nginx 缓存分析报告 ===&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;分析时间: $(</span><span style="color:#61AFEF;">date</span><span style="color:#98C379;">)&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 总请求数</span></span>
<span class="line"><span style="color:#E06C75;">TOTAL</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">wc</span><span style="color:#D19A66;"> -l</span><span style="color:#ABB2BF;"> &lt; </span><span style="color:#98C379;">&quot;</span><span style="color:#E06C75;">$LOG_FILE</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;总请求数: </span><span style="color:#E06C75;">$TOTAL</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 304 响应数（协商缓存命中）</span></span>
<span class="line"><span style="color:#E06C75;">HIT_304</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -c</span><span style="color:#98C379;"> &#39;&quot; 304 &#39;</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$LOG_FILE</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;304 Not Modified: </span><span style="color:#E06C75;">$HIT_304</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 200 响应中带 ETag 的</span></span>
<span class="line"><span style="color:#E06C75;">WITH_ETAG</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -c</span><span style="color:#98C379;"> &#39;etag=&quot;W/&#39;</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$LOG_FILE</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> || </span><span style="color:#56B6C2;">echo</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;带 ETag 响应: </span><span style="color:#E06C75;">$WITH_ETAG</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 各种 Cache-Control 策略分布</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;=== Cache-Control 策略分布 ===&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -oP</span><span style="color:#98C379;"> &#39;cache_control=&quot;\\K[^&quot;]+&#39;</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$LOG_FILE</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">uniq</span><span style="color:#D19A66;"> -c</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -rn</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">head</span><span style="color:#D19A66;"> -20</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 协商缓存命中率</span></span>
<span class="line"><span style="color:#C678DD;">if</span><span style="color:#ABB2BF;"> [ </span><span style="color:#98C379;">&quot;</span><span style="color:#E06C75;">$TOTAL</span><span style="color:#98C379;">&quot;</span><span style="color:#56B6C2;"> -gt</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> ]; </span><span style="color:#C678DD;">then</span></span>
<span class="line"><span style="color:#E06C75;">    HIT_RATE</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;scale=2; </span><span style="color:#E06C75;">$HIT_304</span><span style="color:#98C379;"> * 100 / </span><span style="color:#E06C75;">$TOTAL</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">bc</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;协商缓存命中率: \${</span><span style="color:#E06C75;">HIT_RATE</span><span style="color:#98C379;">}%&quot;</span></span>
<span class="line"><span style="color:#C678DD;">fi</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-3-浏览器端缓存分析" tabindex="-1"><a class="header-anchor" href="#_9-3-浏览器端缓存分析"><span>9.3 浏览器端缓存分析</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 curl 模拟浏览器缓存行为</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 1. 首次请求（无缓存）</span></span>
<span class="line"><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -v</span><span style="color:#98C379;"> https://example.com/style.css</span><span style="color:#ABB2BF;"> 2&gt;&amp;1 | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> &quot;&lt; (ETag|Last-Modified|Cache-Control|Expires):&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 2. 条件请求：使用 ETag</span></span>
<span class="line"><span style="color:#E06C75;">ETAG</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -sI</span><span style="color:#98C379;"> https://example.com/style.css</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> etag</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">awk</span><span style="color:#98C379;"> &#39;{print $2}&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tr</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> &#39;\\r&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -H</span><span style="color:#98C379;"> &quot;If-None-Match: </span><span style="color:#E06C75;">$ETAG</span><span style="color:#98C379;">&quot;</span><span style="color:#D19A66;"> -I</span><span style="color:#98C379;"> https://example.com/style.css</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期: 304 Not Modified</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 3. 条件请求：使用 Last-Modified</span></span>
<span class="line"><span style="color:#E06C75;">LM</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -sI</span><span style="color:#98C379;"> https://example.com/style.css</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> last-modified</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">cut</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;">&#39; &#39;</span><span style="color:#D19A66;"> -f2-</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tr</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> &#39;\\r&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -H</span><span style="color:#98C379;"> &quot;If-Modified-Since: </span><span style="color:#E06C75;">$LM</span><span style="color:#98C379;">&quot;</span><span style="color:#D19A66;"> -I</span><span style="color:#98C379;"> https://example.com/style.css</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期: 304 Not Modified</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 4. 批量检查缓存头</span></span>
<span class="line"><span style="color:#C678DD;">for</span><span style="color:#E06C75;"> url</span><span style="color:#C678DD;"> in</span><span style="color:#98C379;"> &quot;https://example.com/&quot;</span><span style="color:#98C379;"> &quot;https://example.com/style.css&quot;</span><span style="color:#98C379;"> &quot;https://example.com/app.js&quot;</span><span style="color:#ABB2BF;">; </span><span style="color:#C678DD;">do</span></span>
<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;=== </span><span style="color:#E06C75;">$url</span><span style="color:#98C379;"> ===&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">    curl</span><span style="color:#D19A66;"> -sI</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$url</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -iE</span><span style="color:#98C379;"> &quot;(cache-control|etag|expires|last-modified):&quot;</span></span>
<span class="line"><span style="color:#56B6C2;">    echo</span><span style="color:#98C379;"> &quot;&quot;</span></span>
<span class="line"><span style="color:#C678DD;">done</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-4-chrome-devtools-缓存分析" tabindex="-1"><a class="header-anchor" href="#_9-4-chrome-devtools-缓存分析"><span>9.4 Chrome DevTools 缓存分析</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># Chrome DevTools → Network 面板</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看缓存状态：</span></span>
<span class="line"><span># Size 列：</span></span>
<span class="line"><span>#   - &quot;from disk cache&quot; → 磁盘缓存命中（强缓存）</span></span>
<span class="line"><span>#   - &quot;from memory cache&quot; → 内存缓存命中（强缓存）</span></span>
<span class="line"><span>#   - 实际大小 → 从网络获取</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Status Code 列：</span></span>
<span class="line"><span>#   - 200 (from disk cache) → 强缓存命中</span></span>
<span class="line"><span>#   - 304 Not Modified → 协商缓存命中</span></span>
<span class="line"><span>#   - 200 OK → 缓存未命中</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 禁用缓存测试：</span></span>
<span class="line"><span># DevTools → Network → 勾选 &quot;Disable cache&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_9-5-lighthouse-缓存审计" tabindex="-1"><a class="header-anchor" href="#_9-5-lighthouse-缓存审计"><span>9.5 Lighthouse 缓存审计</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 Lighthouse 检查缓存策略</span></span>
<span class="line"><span style="color:#61AFEF;">npx</span><span style="color:#98C379;"> lighthouse</span><span style="color:#98C379;"> https://example.com</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#D19A66;">    --only-categories=performance</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#D19A66;">    --output=json</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#D19A66;">    --output-path=./lighthouse-report.json</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看缓存相关建议</span></span>
<span class="line"><span style="color:#61AFEF;">cat</span><span style="color:#98C379;"> lighthouse-report.json</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">jq</span><span style="color:#98C379;"> &#39;.audits | to_entries[] | select(.key | contains(&quot;cache&quot;)) | {key: .key, score: .value.score, title: .value.title}&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_10-缓存策略常见问题与最佳实践" tabindex="-1"><a class="header-anchor" href="#_10-缓存策略常见问题与最佳实践"><span>10. 缓存策略常见问题与最佳实践</span></a></h2><h3 id="_10-1-常见错误" tabindex="-1"><a class="header-anchor" href="#_10-1-常见错误"><span>10.1 常见错误</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 错误1：所有资源使用相同的缓存策略</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># 所有文件30天缓存，包括HTML</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 正确：按资源类型区分缓存策略</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.html$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 错误2：同时使用 expires 和 add_header Cache-Control</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /images/ {</span></span>
<span class="line"><span style="color:#C678DD;">    expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># 会生成两个 Cache-Control 头</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 正确：只使用一种方式</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /images/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, max-age=2592000&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 错误3：对 API 响应使用强缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/user/ {</span></span>
<span class="line"><span style="color:#C678DD;">    expires </span><span style="color:#D19A66;">1h</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># 用户数据可能1秒就变了</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 正确：API 使用协商缓存或不缓存</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /api/user/ {</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;private, no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ❌ 错误4：忘记加 Vary: Accept-Encoding</span></span>
<span class="line"><span style="color:#C678DD;">gzip </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">gzip_vary </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;  </span><span style="color:#7F848E;font-style:italic;"># 代理可能把压缩版本返回给不支持压缩的客户端</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✅ 正确</span></span>
<span class="line"><span style="color:#C678DD;">gzip_vary </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_10-2-缓存策略决策树" tabindex="-1"><a class="header-anchor" href="#_10-2-缓存策略决策树"><span>10.2 缓存策略决策树</span></a></h3>`,38),i(f,{code:``}),s[4]||=n(`<h3 id="_10-3-缓存最佳实践清单" tabindex="-1"><a class="header-anchor" href="#_10-3-缓存最佳实践清单"><span>10.3 缓存最佳实践清单</span></a></h3><div class="hint-container tip"><p class="hint-container-title">缓存配置检查清单</p><ol><li><strong>带哈希的静态资源</strong>：<code>max-age=31536000, immutable</code></li><li><strong>HTML 入口</strong>：<code>no-cache</code>（每次验证）</li><li><strong>用户私有 API</strong>：<code>private, no-cache</code> 或 <code>no-store</code></li><li><strong>公共 API</strong>：<code>max-age=60-300</code> + <code>stale-while-revalidate</code></li><li><strong>图片/媒体</strong>：<code>max-age=2592000</code>（30天）</li><li><strong>字体</strong>：<code>max-age=31536000, immutable</code></li><li><strong>Service Worker</strong>：<code>no-store</code></li><li><strong>始终添加 <code>Vary: Accept-Encoding</code></strong>：<code>gzip_vary on</code></li><li><strong>生产环境关闭 <code>server_tokens</code></strong>：<code>server_tokens off</code></li><li><strong>CDN 场景使用 <code>public</code></strong>：确保 CDN 能缓存</li></ol></div><h3 id="_10-4-完整生产级缓存配置模板" tabindex="-1"><a class="header-anchor" href="#_10-4-完整生产级缓存配置模板"><span>10.4 完整生产级缓存配置模板</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    root </span><span style="color:#ABB2BF;">/var/www;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 压缩</span></span>
<span class="line"><span style="color:#C678DD;">    gzip </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    gzip_comp_level </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    gzip_types </span><span style="color:#ABB2BF;">text/plain text/css application/javascript application/json image/svg+xml;</span></span>
<span class="line"><span style="color:#C678DD;">    gzip_vary </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    gzip_min_length </span><span style="color:#D19A66;">1024</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 安全</span></span>
<span class="line"><span style="color:#C678DD;">    server_tokens </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 静态资源：带哈希，长缓存 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /assets/ {</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 字体文件 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(woff2?|ttf|otf|eot)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#ABB2BF;">1y;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public, immutable&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Access-Control-Allow-Origin </span><span style="color:#98C379;">&quot;*&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 图片 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.(jpg|jpeg|png|gif|webp|avif|svg|ico)$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        expires </span><span style="color:#D19A66;">30d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;public&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== HTML：协商缓存 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~* </span><span style="color:#E06C75;">\\.html$ </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        etag </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== SPA 路由回退 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        try_files </span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">uri</span><span style="color:#ABB2BF;"> /index.html;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== Service Worker =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> = </span><span style="color:#E06C75;">/sw.js </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;no-store, no-cache, must-revalidate&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== API 代理 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /api/ {</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Cache-Control </span><span style="color:#98C379;">&quot;private, no-cache&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_pass </span><span style="color:#ABB2BF;">http://backend:3000;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">Host $</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">X-Real-IP $</span><span style="color:#E06C75;">remote_addr</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        proxy_set_header </span><span style="color:#ABB2BF;">X-Forwarded-For $</span><span style="color:#E06C75;">proxy_add_x_forwarded_for</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 禁止访问敏感文件 =====</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> ~ </span><span style="color:#E06C75;">/\\. </span><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">        deny </span><span style="color:#D19A66;">all</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_11-参考文档" tabindex="-1"><a class="header-anchor" href="#_11-参考文档"><span>11. 参考文档</span></a></h2><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc7234" target="_blank" rel="noopener noreferrer">RFC 7234 - HTTP Caching</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7232" target="_blank" rel="noopener noreferrer">RFC 7232 - Conditional Requests</a></li><li><a href="https://nginx.org/en/docs/http/ngx_http_headers_module.html#expires" target="_blank" rel="noopener noreferrer">Nginx ngx_http_headers_module: expires</a></li><li><a href="https://nginx.org/en/docs/http/ngx_http_core_module.html#etag" target="_blank" rel="noopener noreferrer">Nginx ngx_http_core_module: etag</a></li><li><a href="https://nginx.org/en/docs/http/ngx_http_core_module.html#if_modified_since" target="_blank" rel="noopener noreferrer">Nginx ngx_http_core_module: if_modified_since</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching" target="_blank" rel="noopener noreferrer">MDN: HTTP Caching</a></li><li><a href="https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/http-caching" target="_blank" rel="noopener noreferrer">Google Web Fundamentals: HTTP Caching</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control" target="_blank" rel="noopener noreferrer">Cache-Control 详解</a></li></ul>`,6)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};